<span class="line"><span style="color:#61AFEF;">cat</span><span style="color:#98C379;"> /var/log/kubernetes/audit.log</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">jq</span><span style="color:#98C379;"> &#39;select(.objectRef.resource==&quot;secrets&quot;)&#39;</span></span>
